/bin/bash -lc "python3 - <<'PY'
import urllib.request, json
for image in ['quay.io/chiujunhao24/udt:borzoi-pytorch-0.5.1-torch2.2.2-cpu','quay.io/chiujunhao24/udt:tensorflow-bio-2.15.1-cpu']:
 repo,tag=image.split('/',1)[1].split(':')
 repo='chiujunhao24/udt'
 print('\\n',image)
 token_url=f'https://quay.io/v2/auth?service=quay.io&scope=repository:{repo}:pull'
 try:
  with urllib.request.urlopen(token_url) as r: token=json.load(r)['token']
  req=urllib.request.Request(f'https://quay.io/v2/{repo}/manifests/{tag}', headers={'Authorization':'Bearer '+token,'Accept':'application/vnd.docker.distribution.manifest.v2+json, application/vnd.oci.image.manifest.v1+json, application/vnd.docker.distribution.manifest.list.v2+json'})
  with urllib.request.urlopen(req) as r:
   data=r.read(); print('manifest bytes',len(data)); m=json.loads(data)
  print('mediaType',m.get('mediaType'),'digest',r.headers.get('Docker-Content-Digest'))
  if 'manifests' in m:
   print('manifest list',[(x['platform'],x['digest']) for x in m['manifests']])
  else:
   config=m['config']; print('config digest',config['digest'])
   cfg_req=urllib.request.Request(f'https://quay.io/v2/{repo}/blobs/{config[\"digest\"]}', headers={'Authorization':'Bearer '+token})
   with urllib.request.urlopen(cfg_req) as cr:
    cfg=json.load(cr); print('created',cfg.get('created')); print('architecture',cfg.get('architecture'),'os',cfg.get('os'));
    print('env',cfg.get('config',{}).get('Env'));
    print('cmd',cfg.get('config',{}).get('Cmd')); print('entrypoint',cfg.get('config',{}).get('Entrypoint'));
 except Exception as e:
  print('ERR',repr(e))
PY"

